xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    const overlay = document.getElementById('caInvoiceConfirmOverlay');
    const approveButton = overlay && overlay.querySelector('.ca-invoice-confirm-approve');
    const closeButtons = overlay && overlay.querySelectorAll('.ca-invoice-confirm-close, .ca-invoice-confirm-cancel');
    let pendingForm = null;

    const closeConfirmation = function () {
        if (!overlay) return;
        overlay.classList.remove('is-open');
        overlay.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
        pendingForm = null;
    };

    const openConfirmation = function (form) {
        if (!overlay) return;
        pendingForm = form;
        const orderError = form.dataset.orderError || '';
        const normalText = document.getElementById('caInvoiceConfirmText');
        const errorText = document.getElementById('caInvoiceOrderError');
        normalText.hidden = Boolean(orderError);
        errorText.hidden = !orderError;
        errorText.textContent = orderError;
        approveButton.hidden = Boolean(orderError);
        document.getElementById('caInvoiceConfirmTitle').textContent = orderError ? 'Fatura Sırası Uyarısı' : 'Fatura Sırasını Kontrol Edin';
        overlay.classList.add('is-open');
        overlay.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
        if (approveButton && !orderError) approveButton.focus();
    };

    if (closeButtons) {
        closeButtons.forEach(function (button) {
            button.addEventListener('click', closeConfirmation);
        });
    }
    if (overlay) {
        overlay.addEventListener('click', function (event) {
            if (event.target === overlay) closeConfirmation();
        });
    }
    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && overlay && overlay.classList.contains('is-open')) {
            closeConfirmation();
        }
    });
    if (approveButton) {
        approveButton.addEventListener('click', function () {
            const form = pendingForm;
            if (!form) return;
            const confirmation = form.querySelector('input[name="invoice_order_confirmed"]');
            if (confirmation) confirmation.value = '1';
            form.dataset.invoiceOrderConfirmed = '1';
            closeConfirmation();
            if (form.requestSubmit) {
                form.requestSubmit();
            } else {
                form.submit();
            }
        });
    }

    document.querySelectorAll('.ca-logo-invoice-form').forEach(function (form) {
        if (form.dataset.submitHandlerBound === '1') return;
        form.dataset.submitHandlerBound = '1';
        form.addEventListener('submit', function (event) {
            if (form.dataset.submitting === '1') {
                event.preventDefault();
                return;
            }
            if (form.dataset.invoiceOrderConfirmed !== '1') {
                event.preventDefault();
                openConfirmation(form);
                return;
            }
            form.dataset.submitting = '1';
            const button = form.querySelector('button[type="submit"]');
            if (button) {
                button.disabled = true;
                button.setAttribute('aria-busy', 'true');
                button.style.opacity = '.75';
                button.style.cursor = 'wait';
                button.innerHTML = '<span class="ca-spinner"></span>Fatura hazırlanıyor';
            }
            // Some mobile WebViews can keep the current page visible
            // after a navigation interruption. Reload to show the real
            // server-side invoice state instead of a permanent spinner.
            window.setTimeout(function () {
                if (form.dataset.submitting === '1') {
                    window.location.reload();
                }
            }, 15000);
        });
    });
});
